/// <summary>
/// Shipment load creation on transfer order
/// </summary>
class METOrderShipmentLoadCreation_TransferOrder extends METOrderShipmentLoadCreation
{
}

Method.Source:
/// <summary>
/// New method for class
/// </summary>
/// <param name = "_inventTransferTable">Table reference</param>
public void new(InventTransferTable      _inventTransferTable)
{
    InventTransferTable = _inventTransferTable;
}

/// <summary>
/// Find or create shipment for the order
/// </summary>
/// <param name = "_findAndCreate">Boolean flag</param>
/// <returns>METSalesOrderShipmentLoadHeader</returns>
public METSalesOrderShipmentLoadHeader findOrCreateOpenShipment(boolean _findAndCreate = false)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METInventTransferTableExt           metInventTransferTableExt = inventTransferTable.metInventTransferTableExt();

    void findOpenShipment()
    {
        select firstonly metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.Route == metInventTransferTableExt.Route                      &&
                metSalesOrderShipmentLoadHeader.RouteStopNum == metInventTransferTableExt.RouteStopNum          &&
                metSalesOrderShipmentLoadHeader.ConfirmedShipDate == inventTransferTable.ShipDate               &&
                metSalesOrderShipmentLoadHeader.Warehouse == inventTransferTable.InventLocationIdFrom           &&
                metSalesOrderShipmentLoadHeader.ToWarehouse == inventTransferTable.InventLocationIdTo           &&
                metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::TransferOrder       &&
                metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;
    }

    findOpenShipment();

    if (metSalesOrderShipmentLoadHeader.RecId != 0 || _findAndCreate == false)
    {
        return metSalesOrderShipmentLoadHeader;
    }

    metSalesOrderShipmentLoadHeader.clear();

    metSalesOrderShipmentLoadHeader.ShipmentId      = NumberSeq::newGetNum(InventParameters::numRefMetShippingID()).num();
    metSalesOrderShipmentLoadHeader.ConfirmedShipDate = inventTransferTable.ShipDate;
    metSalesOrderShipmentLoadHeader.Route           = metInventTransferTableExt.Route;
    metSalesOrderShipmentLoadHeader.RouteStopNum    = metInventTransferTableExt.RouteStopNum;
    metSalesOrderShipmentLoadHeader.Warehouse       = inventTransferTable.InventLocationIdFrom;
    metSalesOrderShipmentLoadHeader.SiteId          = InventLocation::find(inventTransferTable.InventLocationIdFrom).InventSiteId;
    metSalesOrderShipmentLoadHeader.TransactionType = METOrderTransactionType::TransferOrder;
    metSalesOrderShipmentLoadHeader.ShipmentStatus  = MetShipmentStatus::Open;

    metSalesOrderShipmentLoadHeader.ToWarehouse = inventTransferTable.InventLocationIdTo;
    metSalesOrderShipmentLoadHeader.FromWHInternalCustomer = METInventLocation::findByInventLocationId(metSalesOrderShipmentLoadHeader.Warehouse).InternalCustomer;
    metSalesOrderShipmentLoadHeader.FromWHInternalVendor = METInventLocation::findByInventLocationId(metSalesOrderShipmentLoadHeader.Warehouse).InternalVendor;
    metSalesOrderShipmentLoadHeader.ToWHInternalCustomer = METInventLocation::findByInventLocationId(metSalesOrderShipmentLoadHeader.ToWarehouse).InternalCustomer;
    metSalesOrderShipmentLoadHeader.ToWHInternalVendor = METInventLocation::findByInventLocationId(metSalesOrderShipmentLoadHeader.ToWarehouse).InternalVendor;

    if (metSalesOrderShipmentLoadHeader.validateWrite())
    {
        metSalesOrderShipmentLoadHeader.insert();
    }
    else //In case of validation fail, try again to search for open shipment. This may occur when multi thread is running and at same time two picking list executed and system tryed to insert shipment for same parameter.
    {
        findOpenShipment();

        return metSalesOrderShipmentLoadHeader;
    }
    return metSalesOrderShipmentLoadHeader;
}

/// <summary>
/// Create shipment lines
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void createShipmentLines(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    boolean                             shipmentLineInserted;
    METPickingListTransferOrderLine     metPickingListTransferOrderLine;
    METSalesOrderShipmentLoadHeader     metShipmentHeader;
    RecordInsertList                    shipLinesRecordInsertList = new RecordInsertList(tableNum(METSalesOrderShipmentLoadLines), false, false, false, false, false);

    update_recordset metSalesOrderShipmentLoadLines
        setting ShipmentId = _metSalesOrderShipmentLoadHeader.ShipmentId
            where metSalesOrderShipmentLoadLines.OrderNum == inventTransferTable.TransferId
        exists join metShipmentHeader
            where metShipmentHeader.ShipmentId != _metSalesOrderShipmentLoadHeader.ShipmentId      &&
                metshipmentheader.ShipmentStatus == METShipmentStatus::Open;

    while select metPickingListTransferOrderLine
        where metPickingListTransferOrderLine.InventLocationIdFrom == _metSalesOrderShipmentLoadHeader.Warehouse         &&
            metPickingListTransferOrderLine.Route    == _metSalesOrderShipmentLoadHeader.Route                           &&
            metPickingListTransferOrderLine.RouteStopNum == _metSalesOrderShipmentLoadHeader.RouteStopNum                &&
            metPickingListTransferOrderLine.ShippingDateConfirmed == _metSalesOrderShipmentLoadHeader.ConfirmedShipDate  &&
            metPickingListTransferOrderLine.InventLocationIdTo == _metSalesOrderShipmentLoadHeader.ToWarehouse           &&
            metPickingListTransferOrderLine.TransferId == inventTransferTable.TransferId
    {
        metSalesOrderShipmentLoadLines.clear();

        metSalesOrderShipmentLoadLines.ShipmentId       = _metSalesOrderShipmentLoadHeader.ShipmentId;

        metSalesOrderShipmentLoadLines.OrderNum         = metPickingListTransferOrderLine.TransferId;
        metSalesOrderShipmentLoadLines.LineNum          = metPickingListTransferOrderLine.LineNum;
        metSalesOrderShipmentLoadLines.ItemId           = metPickingListTransferOrderLine.ItemId;
        metSalesOrderShipmentLoadLines.Quantity         = metPickingListTransferOrderLine.QtyTransfer;
        metSalesOrderShipmentLoadLines.BackOrder        = metPickingListTransferOrderLine.AllowBackorder;
        metSalesOrderShipmentLoadLines.InventTransId    = metPickingListTransferOrderLine.InventTransId;
        metSalesOrderShipmentLoadLines.PickedQty        = metPickingListTransferOrderLine.PickedQty;
        metSalesOrderShipmentLoadLines.PickingListNum   = metPickingListTransferOrderLine.PickListNum;
        metSalesOrderShipmentLoadLines.PickListPostedBy = metPickingListTransferOrderLine.PickListPostedBy;
        metSalesOrderShipmentLoadLines.WMSOrderTransRecId = metPickingListTransferOrderLine.WMSOrderTransRecId;
        metSalesOrderShipmentLoadLines.PickListPostedDateTime = metPickingListTransferOrderLine.PickListPostedDateTime;
        metSalesOrderShipmentLoadLines.DeliveryInstructions = metPickingListTransferOrderLine.DeliveryInstructions;

        shipLinesRecordInsertList.add(metSalesOrderShipmentLoadLines);

        shipmentLineInserted = true;
    }

    if (shipmentLineInserted)
    {
        shipLinesRecordInsertList.insertDatabase();
    }
}

/// <summary>
/// Init load query
/// </summary>
/// <param name = "_metRoute">Route reference</param>
/// <param name = "_confirmedDate">Confirmed date</param>
/// <param name = "_warehouse">Warehouse</param>
/// <returns>Query</returns>
public Query initFindLoadQuery(METRoute _metRoute, SalesShippingDateConfirmed _confirmedDate, InventLocationId _warehouse)
{
    Query transferLoadQuery;

    transferLoadQuery = super(_metRoute, _confirmedDate, _warehouse);

    transferLoadQuery.dataSourceTable(tableNum(METSalesOrderShipmentLoadHeader)).addRange(fieldNum(METSalesOrderShipmentLoadHeader, ToWarehouse)).value(queryValue(_warehouse));
    transferLoadQuery.dataSourceTable(tableNum(METSalesOrderShipmentLoadHeader)).addRange(fieldNum(METSalesOrderShipmentLoadHeader, TransactionType)).value(queryValue(METOrderTransactionType::SalesOrder));


    return transferLoadQuery;
}
